arguments.command:
python - <<'PY'
from pathlib import Path
text = Path('/app/university_graph.ttl').read_text()
for needle in ['Professor','Full','department','Department','enroll','enrolled','teach','teaching','locatedInCountry','hasName','worksIn','works in','student','Class','University']:
    if needle.lower() in text.lower():
        print(f'=== {needle} ===')
        for line in text.splitlines():
            if needle.lower() in line.lower():
                print(line)
